def _border_runs(values, background):
    """Return contiguous runs of a single non-background color as (color,a,b)."""
    runs = []
    i = 0
    while i < len(values):
        color = values[i]
        if color == background:
            i += 1
            continue
        start = i
        while i < len(values) and values[i] == color:
            i += 1
        runs.append((color, start, i))
    return runs


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Opposite, equal-length border runs act as a pair of matching launch pads.
    candidates = []
    left = _border_runs([grid[r][0] for r in range(h)], background)
    right = _border_runs([grid[r][w - 1] for r in range(h)], background)
    top = _border_runs(grid[0], background)
    bottom = _border_runs(grid[h - 1], background)
    for a in left:
        for b in right:
            if a[0] == b[0] and a[2] - a[1] == b[2] - b[1]:
                candidates.append(("vertical", a, b))
    for a in top:
        for b in bottom:
            if a[0] == b[0] and a[2] - a[1] == b[2] - b[1]:
                candidates.append(("horizontal", a, b))

    for axis, first, second in candidates:
        wall = first[0]
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == background or color == wall:
                    continue
                lane = r if axis == "vertical" else c
                if first[1] <= lane < first[2]:
                    side = 0
                    own, paired = first, second
                elif second[1] <= lane < second[2]:
                    side = 1
                    own, paired = second, first
                else:
                    continue

                offset = lane - own[1]
                paired_lane = paired[1] + offset
                out[r][c] = 4

                if axis == "vertical":
                    # Ray from the seed to its own left/right border run.
                    edge_c = 0 if side == 0 else w - 1
                    step = -1 if edge_c < c else 1
                    cc = c + step
                    while 0 <= cc < w and cc != edge_c:
                        if grid[r][cc] == background:
                            out[r][cc] = color
                        cc += step
                    # Matching ray from the paired border, across its whole row.
                    start_c = w - 1 if side == 0 else 0
                    step = -1 if side == 0 else 1
                    cc = start_c
                    while 0 <= cc < w:
                        if grid[paired_lane][cc] == background:
                            out[paired_lane][cc] = color
                        cc += step
                else:
                    # Ray from the seed to its own top/bottom border run.
                    edge_r = 0 if side == 0 else h - 1
                    step = -1 if edge_r < r else 1
                    rr = r + step
                    while 0 <= rr < h and rr != edge_r:
                        if grid[rr][c] == background:
